const P = $('Params').first().json.payload;
const r = $input.first().json;
const cur = {};
for (const k of ((r.body && r.body.keys) || [])) { cur[k.key_id] = { d: k.description || '', a: k.is_archived }; }
const send = []; const skipped = [];
for (const p of P) {
  const c = cur[p.key_id];
  if (!c) { skipped.push({ key_id: p.key_id, why: 'not found' }); continue; }
  if (c.a) { skipped.push({ key_id: p.key_id, why: 'archived' }); continue; }
  if (c.d.trim()) { skipped.push({ key_id: p.key_id, why: 'already has description', current: c.d }); continue; }
  send.push({ key_id: p.key_id, description: p.description });
}
return [{ json: { body: { keys: send }, send_count: send.length, skipped: skipped, fetch_status: r.statusCode } }];
